## Why Asked
This question evaluates understanding of fundamental sorting algorithms and their practical trade-offs in real-world applications.

## Key Concepts
- Divide and conquer strategies
- Partitioning vs merging approaches
- In-place vs auxiliary space requirements
- Algorithm stability and performance characteristics

## Code Example
```
// Quicksort partition
function partition(arr, low, high) {
  const pivot = arr[high];
  let i = low - 1;
  for (let j = low; j < high; j++) {
    if (arr[j] < pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
  return i + 1;
}

// Mergesort merge
function merge(left, right) {
  const result = [];
  let i = 0, j = 0;

  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }

  return result.concat(left.slice(i)).concat(right.slice(j));
}
```

## Why This Is Asked

This question tests adaptive sorting algorithms, merge logic, and the ability to reason about time complexity in practical, maintainable ways.

## Key Concepts

- **Adaptive sorting**: Using a pre-check to achieve O(n) best-case performance when the array is already sorted
- **Iterative bottom-up mergesort**: Avoiding recursion by iteratively merging sorted subarrays of increasing size
- **Stability and memory usage**: Understanding the trade-offs of O(n) auxiliary space for guaranteed stability

## Code Example

```javascript
function sortWithEarlyMerge(arr) {
  // Early return if already sorted
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] < arr[i - 1]) break;
    if (i === arr.length - 1) return arr;
  }

  // Iterative bottom-up mergesort
  const aux = [...arr];
  let width = 1;

  while (width < arr.length) {
    for (let i = 0; i < arr.length; i += width * 2) {
      const left = i;
      const mid = Math.min(i + width, arr.length);
      const right = Math.min(i + width * 2, arr.length);

      let p = left, q = mid, k = left;
      while (p < mid && q < right) {
        aux[k++] = arr[p] <= arr[q] ? arr[p++] : arr[q++];
      }
      while (p < mid) aux[k++] = arr[p++];
      while (q < right) aux[k++] = arr[q++];
    }

    [arr, aux] = [aux, arr];
    width *= 2;
  }

  return arr;
}
```

## Time Complexity Analysis

- **Best case (O(n))**: Array is already sorted; single linear scan confirms this
- **Worst case (O(n log n))**: Array is reverse sorted; full mergesort required
- **Space complexity**: O(n) for the auxiliary buffer

## Why This Is Asked

This problem tests advanced dynamic programming: partitioning with a non-trivial segment cost that depends on min and max, requiring careful state design and in-loop maintenance of subproblem results. It also validates producing both memoized and iterative solutions and analyzing time/space trade-offs.

## Key Concepts

- DP with partition states
- In-loop maintenance of running min and max
- Top-down memoization vs bottom-up tabulation
- Time complexity: O(D*N^2); Space: O(D*N)

## Code Example

```javascript
// Top-down memoized
function minCost(A, D){
  const N = A.length;
  const memo = Array.from({length:D+1}, ()=> Array(N).fill(null));
  function solve(d, i){
    if (d === 1){
      let mn = Infinity, mx = -Infinity;
      for (let k = 0; k <= i; k++){ mn = Math.min(mn, A[k]); mx = Math.max(mx, A[k]); }
      return mn * mx;
    }
    if (memo[d][i] != null) return memo[d][i];
    let mn = Infinity, mx = -Infinity; let best = Infinity;
    for (let j = i; j >= d-1; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      best = Math.min(best, solve(d-1, j-1) + mn*mx);
    }
    memo[d][i] = best; return best;
  }
  return solve(D, N-1);
}

// Bottom-up
function minCostBottom(A, D){
  const N = A.length, INF = 1e18;
  const dp = Array.from({length:D+1}, ()=> Array(N).fill(INF));
  // base: d = 1
  for (let i = 0; i < N; i++){
    let mn = A[i], mx = A[i];
    for (let j = i; j >= 0; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      if (j === 0) dp[1][i] = Math.min(dp[1][i], mn*mx);
    }
  }
  for (let d = 2; d <= D; d++){
    for (let i = d-1; i < N; i++){
      let mn = A[i], mx = A[i];
      for (let j = i; j >= d-1; j--){
        mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
        dp[d][i] = Math.min(dp[d][i], dp[d-1][j-1] + mn*mx);
      }
    }
  }
  return dp[D][N-1];
}
```

## Why This Is Asked
Tests dynamic dictionary updates with a prefix-based query, combining trie augmentation and edge-case handling. 

## Key Concepts
- Trie with per-node passCount to track subtree content
- O(length of word) updates for insert/delete
- LCP query via prefix traversal until no valid child
- Edge cases: duplicates, deleting absent words, memory pruning

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.cnt = 0;
  }
}
class DynamicDict {
  constructor(){ this.root = new TrieNode(); this.hasWord=new Set(); }
  insert(w){ if(this.hasWord.has(w)) return; this.hasWord.add(w); let node=this.root; for(const ch of w){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node=node.next.get(ch); node.cnt++; } }
  delete(w){ if(!this.hasWord.has(w)) return; this.hasWord.delete(w); let node=this.root; for(const ch of w){ const child=node.next.get(ch); child.cnt--; if(child.cnt===0){ node.next.delete(ch); } node=child; } }
  lcpQuery(q){ let node=this.root, depth=0, res=0; for(const ch of q){ if(!node.next.has(ch)) break; node=node.next.get(ch); depth++; if(node.cnt>0) res=depth; } return res; }
}
```

